// The state and status lists are never NULL: an empty list selects every state or
// status. A station without a status row has never connected.
func (q *Queries) ListChargeStationRecords(ctx context.Context, arg ListChargeStationRecordsParams) ([]ListChargeStationRecordsRow, error) {
	rows, err := q.db.Query(ctx, ListChargeStationRecords,
		arg.OrgIds,
		arg.LocationID,
		arg.States,
		arg.Vendor,
		arg.Model,
		arg.Connected,
		arg.Statuses,
		arg.Query,
		arg.AfterKey,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListChargeStationRecordsRow{}
	for rows.Next() {
		var i ListChargeStationRecordsRow
		if err := rows.Scan(
			&i.ChargeStationID,
			&i.OrgID,
			&i.LocationID,
			&i.DisplayName,
			&i.MaxCapacityKw,
			&i.AllowAnyToken,
			&i.State,
			&i.StateChangedAt,
			&i.StateReason,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.OcppVersion,
			&i.Vendor,
			&i.Model,
			&i.SerialNumber,
			&i.FirmwareVersion,
			&i.Iccid,
			&i.Imsi,
			&i.MeterSerialNumber,
			&i.MeterType,
			&i.LastBootAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

